+#!/usr/bin/env bash
+# GRPO | Qwen3-30B-A3B (MoE) | DAPO-Math-17k | Megatron training | MXFP4 routed experts | NVIDIA Blackwell (SM100+)
+#
+# PRECISION=mxfp4_qat trains in BF16 with ModelOpt MXFP4 QAT on the routed experts and serves the rollout with MXFP4
+# experts; PRECISION=mxfp4 quantizes the rollout's experts only (no QAT); PRECISION=bf16 runs the same job in BF16, as
+# the baseline. MXFP4 covers the routed experts only: dense layers, lm_head, embeddings and routers stay in BF16.
+# The rollout serves the experts through vLLM's DeepGEMM FP4 MoE kernel, which needs SM100/SM120. The defaults were
+# tested on one 4xB300 node (4xB200 untested) and run without a validation set. See docs/low_precision/mxfp4_qat.md.
+
+set -xeuo pipefail
+export CUDA_DEVICE_MAX_CONNECTIONS=1
+
+########################### user-adjustable ###########################
+INFER_BACKEND=${INFER_BACKEND:-vllm}
+PRECISION=${PRECISION:-mxfp4_qat}
+
+MODEL_PATH=${MODEL_PATH:-Qwen/Qwen3-30B-A3B}
+TRAIN_FILE=${TRAIN_FILE:-$HOME/data/dapo-math-17k/train.parquet}
+# only read when TEST_FREQ > 0
+VAL_FILE=${VAL_FILE:-$TRAIN_FILE}
+NNODES=${NNODES:-1}
+NGPUS_PER_NODE=${NGPUS_PER_NODE:-4}
+
+train_batch_size=${TRAIN_BATCH_SIZE:-64}
+ppo_mini_batch_size=${PPO_MINI_BATCH_SIZE:-32}
+max_prompt_length=${MAX_PROMPT_LENGTH:-1024}
+max_response_length=${MAX_RESPONSE_LENGTH:-8192}
+max_token_len_per_gpu=${MAX_TOKEN_LEN_PER_GPU:-20480}
+
+actor_lr=${ACTOR_LR:-1e-6}
+kl_loss_coef=${KL_LOSS_COEF:-0.001}
+entropy_coeff=${ENTROPY_COEFF:-0}
+
+actor_tp=${ACTOR_TP:-2}
+actor_pp=${ACTOR_PP:-1}
+actor_ep=${ACTOR_EP:-2}
+# offload parameters and optimizer state while the rollout runs
+offload=${OFFLOAD:-True}
+# keep the whole optimizer on the CPU: Adam's FP32 state for 30B does not fit next to training on four GPUs
+optimizer_cpu_offload=${OPTIMIZER_CPU_OFFLOAD:-True}
+
+rollout_tp=${ROLLOUT_TP:-2}
+rollout_gpu_mem_util=${ROLLOUT_GPU_MEM_UTIL:-0.4}
+rollout_max_num_seqs=${ROLLOUT_MAX_NUM_SEQS:-256}
+rollout_n=${ROLLOUT_N:-8}
+
+total_epochs=${TOTAL_EPOCHS:-1}
+total_training_steps=${TOTAL_TRAINING_STEPS:-null}
+save_freq=${SAVE_FREQ:--1}
+test_freq=${TEST_FREQ:--1}
+# the same seed gives every arm the same data order, so steps pair across arms
+seed=${SEED:-1}
+
+project_name=${PROJECT_NAME:-verl_grpo_dapo_mxfp4}
+experiment_name=${EXPERIMENT_NAME:-qwen3_30b_a3b_megatron_${INFER_BACKEND}_${PRECISION}}
+########################### end user-adjustable ###########################
+
+########################### parameter arrays ###########################
+
+TF=actor_rollout_ref.actor.megatron.override_transformer_config
+case "${PRECISION}" in
+    mxfp4_qat)
+        PRECISION_ARGS=(
+            # MXFP4 rollout experts: verl exports MXFP4 expert weights (1x32 groups, E8M0 scales); DeepGEMM quantizes the
+            # expert activations to FP8 (1x128) at run time
+            actor_rollout_ref.rollout.quantization.moe=MXFP4
+            # ModelOpt QAT fake-quantizes the routed experts the same way during training (MXFP4 weights, MXFP8 inputs)
+            actor_rollout_ref.actor.megatron.qat.enable=True
+            actor_rollout_ref.actor.megatron.qat.mode=mxfp4
+        )
+        ;;
+    mxfp4)
+        PRECISION_ARGS=(
+            actor_rollout_ref.rollout.quantization.moe=MXFP4
+        )
+        ;;
+    bf16)
+        PRECISION_ARGS=()
+        ;;
+    *)
+        echo "PRECISION must be mxfp4_qat, mxfp4 or bf16, got '${PRECISION}'" >&2
+        exit 1
+        ;;
+esac
+
+DATA=(
+    algorithm.adv_estimator=grpo
+    algorithm.use_kl_in_reward=False
+    data.train_files="$TRAIN_FILE"
+    data.val_files="$VAL_FILE"
+    data.train_batch_size=${train_batch_size}
+    data.max_prompt_length=${max_prompt_length}
+    data.max_response_length=${max_response_length}
+    data.filter_overlong_prompts=True
+    data.truncation='error'
+    data.seed=${seed}
+)
+
+MODEL=(
+    actor_rollout_ref.model.path="$MODEL_PATH"
+)
+
+OPTIM=+actor_rollout_ref.actor.optim.override_optimizer_config
+ACTOR=(
+    actor_rollout_ref.actor.optim.lr=${actor_lr}
+    actor_rollout_ref.actor.ppo_mini_batch_size=${ppo_mini_batch_size}
+    actor_rollout_ref.actor.ppo_micro_batch_size_per_gpu=1
+    actor_rollout_ref.actor.use_dynamic_bsz=True
+    actor_rollout_ref.actor.ppo_max_token_len_per_gpu=${max_token_len_per_gpu}
+    actor_rollout_ref.actor.use_kl_loss=True
+    actor_rollout_ref.actor.kl_loss_coef=${kl_loss_coef}
+    actor_rollout_ref.actor.kl_loss_type=low_var_kl
+    actor_rollout_ref.actor.entropy_coeff=${entropy_coeff}
+    actor_rollout_ref.actor.megatron.tensor_model_parallel_size=${actor_tp}
+    actor_rollout_ref.actor.megatron.pipeline_model_parallel_size=${actor_pp}
+    actor_rollout_ref.actor.megatron.expert_model_parallel_size=${actor_ep}
+    actor_rollout_ref.actor.megatron.param_offload=${offload}
+    actor_rollout_ref.actor.megatron.optimizer_offload=${offload}
+    ${OPTIM}.optimizer_cpu_offload=${optimizer_cpu_offload}
+    ${OPTIM}.overlap_cpu_optimizer_d2h_h2d=${optimizer_cpu_offload}
+    ${OPTIM}.use_precision_aware_optimizer=${optimizer_cpu_offload}
+    ${OPTIM}.optimizer_offload_fraction=1.0
+    ++${TF}.recompute_granularity=full
+    ++${TF}.recompute_method=uniform
+    ++${TF}.recompute_num_layers=1
+    ++${TF}.moe_grouped_gemm=True
+    ++${TF}.moe_token_dispatcher_type=alltoall
+    ++${TF}.moe_router_dtype=fp32
+)
+
+ROLLOUT=(
+    actor_rollout_ref.rollout.name=${INFER_BACKEND}
+    actor_rollout_ref.rollout.tensor_model_parallel_size=${rollout_tp}
+    actor_rollout_ref.rollout.gpu_memory_utilization=${rollout_gpu_mem_util}
+    actor_rollout_ref.rollout.max_num_seqs=${rollout_max_num_seqs}
+    actor_rollout_ref.rollout.n=${rollout_n}
+    actor_rollout_ref.rollout.log_prob_micro_batch_size_per_gpu=2
+    actor_rollout_ref.rollout.log_prob_use_dynamic_bsz=True
+    actor_rollout_ref.rollout.log_prob_max_token_len_per_gpu=${max_token_len_per_gpu}
+)
+
+REF=(
+    actor_rollout_ref.ref.log_prob_micro_batch_size_per_gpu=2
+    actor_rollout_ref.ref.log_prob_use_dynamic_bsz=True
+    actor_rollout_ref.ref.log_prob_max_token_len_per_gpu=${max_token_len_per_gpu}
+    actor_rollout_ref.ref.megatron.tensor_model_parallel_size=${actor_tp}
+    actor_rollout_ref.ref.megatron.pipeline_model_parallel_size=${actor_pp}
+    actor_rollout_ref.ref.megatron.expert_model_parallel_size=${actor_ep}
+    actor_rollout_ref.ref.megatron.param_offload=${offload}
+)
+
+TRAINER=(
+    trainer.critic_warmup=0
+    trainer.logger='["console","wandb"]'
+    trainer.project_name=${project_name}
+    trainer.experiment_name=${experiment_name}
+    trainer.n_gpus_per_node=${NGPUS_PER_NODE}
+    trainer.nnodes=${NNODES}
+    trainer.save_freq=${save_freq}
+    trainer.test_freq=${test_freq}
+    trainer.val_before_train=False
+    trainer.total_epochs=${total_epochs}
+    trainer.total_training_steps=${total_training_steps}
+)
+
+EXTRA=(
+    model_engine=megatron
+)
+
+########################### launch ###########################
+# uv (set VERL_USE_UV=0 for system python): GPU vllm/sglang × megatron run the driver and every Ray worker
+# (runtime_env.py_executable) through `uv run` on the matching extras of the committed uv.lock;
+# other backends / NPU fall back to ambient python. Run from the verl repo root.
+LAUNCH=(python3)
+RAY=(ray_kwargs.ray_init.runtime_env.py_executable=null)
+if [ "${VERL_USE_UV:-1}" != 0 ] && [ "${DEVICE:-gpu}" = gpu ] && { [ "${INFER_BACKEND}" = vllm ] || [ "${INFER_BACKEND}" = sglang ]; }; then
+    LAUNCH=(uv run --frozen --all-packages --extra "${INFER_BACKEND}" --extra megatron python3)
+    RAY=(ray_kwargs.ray_init.runtime_env.py_executable="uv -v run --frozen --all-packages --extra ${INFER_BACKEND} --extra megatron")
+fi
+"${LAUNCH[@]}" -m verl.trainer.main_ppo \
+    "${DATA[@]}" \
+    "${MODEL[@]}" \
+    "${ACTOR[@]}" \
+    "${ROLLOUT[@]}" \
+    "${REF[@]}" \
+    "${TRAINER[@]}" \
+    "${PRECISION_ARGS[@]}" \
+    "${EXTRA[@]}" \
+    "${RAY[@]}" \
+    "$@"
